#!/usr/bin/env bash
# Official EAT eval (generated by `kb4090 prepare-eat`). Do not edit during a run.
# Prints one line per problem and a final "SCORE: <x>" (higher is better).
# SCORE = geometric mean verified speedup vs PyTorch eager TF32; unchanged stub = 1.0;
# any FAIL / INVALID / SUSPECT solution makes SCORE 0.
set -uo pipefail
cd "$(dirname "$0")/.."
if [ -f eat/env.sh ]; then
  # shellcheck disable=SC1091
  source eat/env.sh
fi
kb4090 eat-score --repo .
status=$?
if [ $status -ne 0 ]; then
  echo "SCORE: 0"
fi
